(()=>{'use strict';
const $=id=>document.getElementById(id),E=QE,M=QM,C=QC,keys=['overview','case','spc','msa','tools','eightd','fmea','apqp','audits','value','learn','downloads'];
const storage='barkati-quality-connected-1';let lang='en',theme='light',state,storageOK=true,view='overview',edit=null,msaType='crossed',tool='pareto',msaLast=null,toolLast=null;
try{lang=localStorage.getItem(storage+'-lang')||'en';theme=localStorage.getItem(storage+'-theme')||'light';const raw=localStorage.getItem(storage);state=raw?M.validate(JSON.parse(raw)):M.demo();}catch(err){state=M.demo();storageOK=false;setTimeout(()=>toast('Stored case could not be loaded: '+err.message+'. Import your last JSON backup.'),400);}
if(!C.ui[lang])lang='en';const t=k=>C.ui[lang][k]||k;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=4)=>typeof v==='number'&&Number.isFinite(v)?v.toLocaleString('en-US',{maximumFractionDigits:d}):'Not defined';
const pct=v=>fmt(v*100,2)+'%';const today=()=>new Date().toISOString().slice(0,10);
function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',6500);}
function save(event){if(event)M.record(state,event);try{localStorage.setItem(storage,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('Browser storage unavailable or full. Export JSON now to retain your case.');}status();}
function status(){$('statusbar').innerHTML=`<span>${esc(state.id)} · ${esc(state.product)} · ${esc(state.characteristic)} <span class="pill ${state.synthetic?'warn':''}">${state.synthetic?'SYNTHETIC DEMO':'USER CASE'}</span></span><span>${storageOK?t('saved'):'Storage unavailable — export JSON'} · revision ${state.revision||1}</span>`;}
function study(){try{return E.spc(state.study.groups,{...state.study,...state.spec});}catch{return null;}}
function input(id,label,value,type='text',attrs=''){return `<label>${esc(label)}<input id="${id}" type="${type}" value="${esc(value)}" ${attrs}></label>`;}
function area(id,label,value,cls=''){return `<label>${esc(label)}<textarea id="${id}" class="${cls}">${esc(value)}</textarea></label>`;}
function select(id,label,opts,value){return `<label>${esc(label)}<select id="${id}">${opts.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${value===v?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;}
const btn=(label,action,cls='')=>`<button data-action="${action}" class="${cls}">${label}</button>`;
function title(name,desc){return `<div class="titleline"><div><span class="eyebrow">Barkati Quality OS</span><h1>${name}</h1><p class="muted">${desc}</p></div>${btn('Method guide','learn')}</div>`;}
function metrics(entries){return `<div class="kpis">${entries.map(([label,value,note])=>`<div class="kpi"><span>${label}</span><strong>${value}</strong><small>${note||''}</small></div>`).join('')}</div>`;}
function list(items){return `<ul class="bullet">${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;}
function chart(s,baseline){if(!s||!s.values.length)return '';let min=Math.min(...s.values,...s.lower),max=Math.max(...s.values,...s.upper),pad=(max-min)*.15||1;min-=pad;max+=pad;const W=860,H=290,p={l:75,r:30,t:28,b:40},x=i=>p.l+i*(W-p.l-p.r)/Math.max(1,s.values.length-1),y=v=>p.t+(max-v)/(max-min)*(H-p.t-p.b);const path=arr=>arr.map((v,i)=>(i?'L':'M')+x(i).toFixed(2)+','+y(v).toFixed(2)).join(' ');const sig=new Set(s.signals.map(a=>a.at-1));let text=`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(s.name)} control chart"><title>${esc(s.name)} control chart. ${s.signals.length} selected signals.</title>`;for(let i=0;i<=4;i++){const v=min+(max-min)*i/4;text+=`<line class="axis" x1="${p.l}" x2="${W-p.r}" y1="${y(v)}" y2="${y(v)}"/><text x="${p.l-8}" y="${y(v)+4}" text-anchor="end" font-size="11">${fmt(v,5)}</text>`;}text+=`<path d="${path(s.lower)}" class="limit" fill="none"/><path d="${path(s.upper)}" class="limit" fill="none"/><line class="center" x1="${p.l}" x2="${W-p.r}" y1="${y(s.center)}" y2="${y(s.center)}"/><path d="${path(s.values)}" class="series"/>`;if(baseline&&baseline<s.values.length)text+=`<line class="axis" stroke-dasharray="3 4" x1="${x(baseline-.5)}" x2="${x(baseline-.5)}" y1="${p.t}" y2="${H-p.b}"/><text x="${x(baseline-.5)+4}" y="18" font-size="10">Monitoring</text>`;text+=s.values.map((v,i)=>`<circle class="${sig.has(i)?'signal':'point'}" cx="${x(i)}" cy="${y(v)}" r="${sig.has(i)?4.5:2.8}"><title>Row ${i+1+(s.offset||0)}: ${v}</title></circle>`).join('');text+=`<text x="${W/2}" y="${H-7}" font-size="11" text-anchor="middle">Time-ordered row sequence · ${esc(s.name)}</text><text x="${p.l}" y="17" font-size="11">CL ${fmt(s.center,5)} · limits in red</text></svg>`;return text;}
function table(headers,rows){return `<div class="scroll"><table><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function registry(key,cols){const data=state[key],ff=M.fields[key],fields=cols||ff.slice(0,5).map(f=>f[0]);return `<section class="card"><div class="cardtop"><h2>${({evidence:'Evidence register',causes:'Three-leg causal register',tests:'Reproduction & falsification tests',actions:'Corrective actions',exposure:'Containment coverage',risks:'Connected risk register',controlPlan:'Control Plan changes',deliverables:'Submission evidence',audits:'Audit findings'})[key]}</h2><div class="row"><button data-add="${key}">${t('add')}</button><button data-csv="${key}">CSV</button></div></div>${data.length?table(['ID',...fields.map(k=>ff.find(f=>f[0]===k)?.[1]||k),''],data.map(r=>[esc(r.id),...fields.map(k=>esc(typeof r[k]==='boolean'?(r[k]?'Yes':'No'):r[k])),`<button data-edit="${key}" data-id="${esc(r.id)}">${t('edit')}</button>`])):`<div class="empty">No records. Add the first record to this case.</div>`}</section>`;}
function gateCards(){return `<div class="stepgrid">${E.eightDGates(state).map(g=>`<div class="step ${g.eligible?'ready':''}" title="${esc(g.reason)}"><strong>${g.id}</strong>${g.eligible?'READY':'BLOCKED'}</div>`).join('')}</div>`;}
function overview(){const s=study(),g=E.gate(state,s),ap=M.approvalGate(state),eg=E.eightDGates(state);return `<section class="hero"><div><span class="eyebrow">Connected engineering workspace</span><h1>${t('title')}</h1><p>${t('subtitle')}</p><div class="row">${btn('Open measurement study','spc','primary')}${btn('Run the guided demonstration','tour')}</div></div><div class="heroaside"><small>Current decision</small><br><strong>${g.status}</strong><p>${g.blocks.length} statistical review items · ${eg.filter(x=>x.eligible).length}/8 investigation gates</p></div></section>${metrics([['Observations',s?.observations||0,'Time-ordered measurements'],['Chart signals',s?.signals.length??'—','Location and dispersion'],['Open actions',state.actions.filter(a=>a.status!=='effective').length,'Evidence-driven closure'],['Submission evidence',ap.complete+'/'+ap.total,'Reviewed deliverables']])}<div class="grid"><section class="card"><div class="cardtop"><h2>Process behaviour</h2><span class="pill warn">${s?s.mode:'No study'}</span></div>${s?chart(s.main,s.baseline):'<p>Add data to start the study.</p>'}${btn('Inspect both charts and limits','spc')}</section><section class="card"><h2>Next engineering decisions</h2>${list(g.blocks.length?g.blocks:['Statistical prerequisites complete. A named engineering decision is still required.'])}<div class="row">${btn('Review case evidence','case')}${btn('Create / review investigation','eightd')}</div></section></div><section class="card"><div class="cardtop"><h2>One case across Core Tools</h2><span class="pill">Stable record IDs</span></div><div class="flow">${[['Measure','MSA and raw data'],['Monitor','SPC and reaction'],['Investigate','Evidence and causes'],['Prevent','FMEA and Control Plan'],['Approve','APQP and audit records']].map(([a,b])=>`<div class="node"><b>${a}</b><small>${b}</small></div>`).join('')}</div>${gateCards()}</section>`;}
function caseView(){return title('Case & measurement data','Define the engineering context once. Keep the source order and explicit specification.')+`<form id="caseForm" class="card"><h2>Case identity and specification</h2><div class="formgrid">${input('caseTitle','Case title',state.title)}${input('owner','Case owner',state.owner)}${input('customer','Customer',state.customer)}${input('product','Product / part',state.product)}${input('process','Process',state.process)}${input('equipment','Equipment',state.equipment)}${input('characteristic','Characteristic ID',state.characteristic)}${input('specName','Characteristic name',state.spec.name)}${input('unit','Unit',state.spec.unit)}${input('drawing','Specification reference / revision',state.spec.drawing)}${input('lsl','Lower specification',state.spec.lsl,'number','step="any" required')}${input('usl','Upper specification',state.spec.usl,'number','step="any" required')}${input('required','Configured capability threshold',state.spec.required,'number','step="any" min="0.01" required')}${select('synthetic','Dataset classification',[['true','Synthetic / demonstration'],['false','User case']],String(state.synthetic))}</div><div class="note">Specifications are product requirements. They do not determine statistical control limits.</div><button class="primary">${t('save')}</button></form>`+registry('evidence',['title','source','statement','verifiedBy'])+`<section class="card"><h2>Recent case activity</h2><p class="muted">Local activity history is editable through exported JSON; it is not a tamper-proof audit trail.</p>${table(['Revision','Time','Activity'],state.auditLog.slice(-12).reverse().map(r=>[esc(r.revision),esc(r.at),esc(r.event)]))}</section>`;}
function spcView(){const s=study(),g=E.gate(state,s);return title('SPC & capability','Baseline estimates stay fixed when monitoring rows are added. Both charts inform the review.')+`<div class="grid"><section class="card"><form id="spcForm"><h2>Study setup</h2><div class="formgrid">${select('chartMode','Chart',[['imr','I–MR'],['xbarR','Xbar–R'],['xbarS','Xbar–S']],state.study.mode)}${input('baseline','Baseline row count',state.study.baseline,'number','min="2" step="1" required')}</div><label><input id="extended" type="checkbox" ${state.study.extended?'checked':''}> Add 8-on-one-side and 6-point-trend rules</label>${area('measurements','Numeric data: one subgroup per row; comma, semicolon or tab columns. No headers. Decimal point only.',state.study.groups.map(r=>r.join(',')).join('\n'),'dataarea')}<p class="muted">Blank lines are ignored. Blank cells, text, non-finite values and incomplete rows are rejected. Nothing is silently imputed or trimmed.</p><div class="row"><button class="primary">Calculate & save</button>${btn('Import CSV','importMeasurements')}${btn('Export data CSV','exportMeasurements')}</div><p class="error" id="calcError"></p></form></section><section class="card"><h2>Method and review evidence</h2><form id="governanceForm" class="stack">${area('msaEvidence','Measurement suitability evidence / reference',state.governance.msaEvidence)}${area('modelEvidence','Distribution, independence and subgroup rationale',state.governance.modelEvidence)}${input('reviewer','Named statistical reviewer',state.governance.reviewer)}<button>${t('save')}</button></form><div class="note"><strong>${g.status}</strong>${list(g.blocks)}</div>${btn('Create investigation from this study','investigate','primary')}</section></div>${s?metrics([['Cp / Cpk',fmt(s.capability.cp,2)+' / '+fmt(s.capability.cpk,2),'Within estimate; baseline only'],['Pp / Ppk',fmt(s.capability.pp,2)+' / '+fmt(s.capability.ppk,2),'Overall estimate; baseline only'],['Within σ',fmt(s.within,6),state.spec.unit],['Outside specification',s.capability.outOfSpec,'All observed readings']])+`<section class="card"><h2>${s.main.name}</h2>${chart(s.main,s.baseline)}</section><section class="card"><h2>${s.disp.name}</h2>${chart(s.disp,s.baseline-(s.disp.offset||0))}</section><section class="card"><h2>Signals and interpretation</h2>${s.signals.length?table(['Chart','Rule','Row','Value'],s.signals.map(r=>[esc(r.chart),esc(r.rule),r.at,fmt(r.value,6)])):'<p>No selected signal detected.</p>'}${list(s.warnings)}<p>Normal-model capability values remain descriptive until measurement, stability and model suitability are reviewed. This application never releases product automatically.</p></section>`:'<div class="note">No valid study. Enter data and calculate.</div>'}`;}
function msaDemo(type){if(type==='crossed'||type==='nested'){let rows=[];for(let o=0;o<3;o++)for(let p=0;p<10;p++)for(let r=0;r<2;r++)rows.push(`${type==='nested'?'O'+o+'-':''}P${p+1},O${o+1},${(10+p*.012+o*.001+(r?1:-1)*(.0008+((p+o)%3)*.0002)).toFixed(5)}`);return rows.join('\n');}if(type==='attribute')return ['OK,OK','OK,OK','NOK,NOK','OK,NOK','NOK,NOK','OK,OK','NOK,NOK','NOK,OK','OK,OK','NOK,NOK'].join('\n');if(type==='linearity')return Array.from({length:15},(_,i)=>{const x=5+Math.floor(i/3)*2;return x+','+(x+.004*x+(i%3-1)*.005).toFixed(5);}).join('\n');return Array.from({length:30},(_,i)=>(10.001+Math.sin(i*1.7)*.002).toFixed(5)).join('\n');}
function msaView(){const draft=state.msaDraft;return title('Measurement studies','Select the study design explicitly. Interpret estimates against the intended measurement decision.')+`<div class="grid"><section class="card"><form id="msaForm">${select('msaType','Study',[['crossed','Crossed GR&R — balanced ANOVA'],['nested','Nested GR&R — balanced ANOVA'],['bias','Bias and 95% interval'],['type1','Type 1 Cg / Cgk'],['linearity','Linearity of bias'],['attribute','Pairwise attribute agreement / Kappa'],['stability','Stability — I–MR'],['resolution','Resolution ratio']],msaType)}<div class="formgrid">${input('reference','Traceable reference',10,'number','step="any"')}${input('tolerance','Tolerance width',.1,'number','step="any" min="0.0000001"')}${input('fraction','Type 1 tolerance allocation',.2,'number','min="0.01" max="0.99" step="0.01"')}${input('resolution','Instrument resolution',.001,'number','step="any" min="0.0000001"')}</div><p id="msaHint" class="note">${msaHint()}</p>${area('msaData','Study readings — no header',draft?.type===msaType?draft.text:msaDemo(msaType),'dataarea')}<div class="row"><button class="primary">Calculate study</button>${btn('Load study example','msaDemo')}</div><p id="msaError" class="error"></p></form></section><section class="card"><h2>Study result</h2><div id="msaResult"><p class="muted">Calculate to inspect estimates and limitations.</p></div></section></div><section class="card"><h2>Saved study records</h2><p class="muted">Use “Add to evidence” after calculation to retain inputs and results in the case export. Verification remains a named reviewer’s task.</p>${table(['Study','Date','Evidence'],(state.msaStudies||[]).map(r=>[esc(r.type),esc(r.at),esc(r.evidenceId)]))}</section>`;}
function msaHint(){return ['crossed','nested'].includes(msaType)?'Columns: part ID, operator ID, measured value. Equal repeat counts required. Nested part IDs must be unique across operators.':msaType==='linearity'?'Columns: reference value, observed value. At least three pairs with varied reference values.':msaType==='attribute'?'Columns: rating A, rating B. Use consistent category names. Pairwise unweighted Kappa.':'One numeric observation per row. The resolution calculator uses the tolerance and instrument-resolution fields.';}
function resultMetrics(r){const pairs=Object.entries(r).filter(([,v])=>typeof v==='number'||v===null);return pairs.map(([k,v])=>`<div class="metricline"><span>${esc(k)}</span><b>${fmt(v,6)}</b></div>`).join('');}
function toolsView(){return title('Quality tools','Use explicit data and assumptions. Save analyses into the same case evidence.')+`<div class="grid"><section class="card"><form id="toolsForm">${select('toolType','Tool',[['pareto','Pareto / check-sheet counts'],['histogram','Histogram'],['scatter','Scatter and simple regression'],['sampling','Binomial sampling / OC curve'],['p','p chart'],['np','np chart'],['c','c chart'],['u','u chart']],tool)}<div id="toolParams">${tool==='sampling'?`<div class="formgrid">${input('sampleN','Sample size n',50,'number','min="1" max="100000" step="1"')}${input('sampleC','Acceptance number c',1,'number','min="0" step="1"')}${input('defectP','Nonconforming probability p',.02,'number','min="0" max="1" step="0.001"')}</div>`:''}</div>${area('toolData',toolHint(),toolDemo(tool),'dataarea')}<button class="primary">Calculate</button><p id="toolError" class="error"></p></form></section><section class="card"><h2>Analysis</h2><div id="toolResult"><p class="muted">Results appear here.</p></div></section></div>`;}
function toolHint(){return tool==='pareto'?'Category,count (no header)':tool==='scatter'?'x,y pairs (no header)':tool==='p'||tool==='np'?'Nonconforming units, inspected units':tool==='u'?'Nonconformities, exposure units':tool==='sampling'?'Data below are unused for the binomial model; edit n, c and p above.':'One numeric reading per row';}
function toolDemo(k){return k==='pareto'?'Burr,34\nWidth,18\nSurface,11\nPacking,7':k==='scatter'?'1,2.1\n2,4.2\n3,5.8\n4,8.3\n5,9.7':k==='p'||k==='np'||k==='u'?'2,100\n3,100\n1,100\n2,100\n9,100\n1,100':k==='c'?'2\n3\n1\n2\n9\n1':k==='sampling'?'':state.study.groups.flat().slice(0,80).join('\n');}
function eightdView(){const gates=E.eightDGates(state);return title('Investigation & 8D','Occurrence, escape and systemic paths share evidence, tests and corrective actions.')+gateCards()+`<div class="grid"><section class="card"><h2>Problem definition</h2><form id="problemForm" class="formgrid">${[['team','Team'],['what','What / defect'],['where','Where'],['when','When / change point'],['howMany','How many / exposure'],['isNot','IS NOT boundary'],['lessons','Lessons and recurrence scope']].map(([k,l])=>area('problem-'+k,l,state.investigation[k])).join('')}<div><button class="primary">${t('save')}</button></div></form></section><section class="card"><h2>Evidence challenge</h2><span class="pill">Deterministic checks · offline</span>${list(E.challenge(state,study()))}<p class="muted">These are investigation prompts, not AI-generated root-cause conclusions.</p><details><summary>Gate prerequisites</summary>${list(gates.map(g=>g.id+': '+g.reason))}</details></section></div><section class="card"><h2>Causal paths</h2><div class="grid three">${['occurrence','escape','systemic'].map(l=>`<div><h3>${l.toUpperCase()}</h3><div class="stack">${state.causes.filter(n=>n.lane===l).map(n=>`<article><b>${esc(n.id)} · ${esc(n.label)}</b><small>${esc(n.status)} · evidence ${esc(n.evidenceId||'missing')} · test ${esc(n.testId||'missing')}</small></article>`).join('')||'<p class="muted">No hypothesis recorded.</p>'}</div></div>`).join('')}</div></section>`+registry('causes',['lane','label','status','evidenceId','testId','acceptedBy'])+registry('tests',['causeId','name','expectedIfTrue','expectedIfFalse','result','conclusion'])+registry('exposure',['location','quantity','checked','rejected','cleanPoint','evidenceId'])+registry('actions',['causeId','title','owner','due','status','verification','validation'])+`<section class="card"><h2>Human closure record</h2><p>All D1–D7 prerequisites must be complete. Further substantive case edits invalidate this closure record.</p><form id="closureForm" class="formgrid">${input('closureApprover','Approver',state.investigation.approver)}${input('closureReference','Approval reference',state.investigation.approvalReference)}${input('closureDate','Closure date',state.investigation.closureDate||today(),'date')}<div><button class="primary">Record closure</button></div><p id="closureError" class="error wide"></p></form></section>`;}
function fmeaView(){const linkIssues=M.links(state);return title('Connected FMEA & Control Plan','Connect risk assumptions across design, process and equipment. Propagate review, never silent approval.')+`<section class="card"><div class="cardtop"><h2>Risk relationships</h2><div class="row">${btn('Import AP reference JSON','apImport')}${btn('Flag linked risks for review','propagate')}</div></div><div class="flow">${state.risks.map(r=>`<div class="node"><span class="pill">${esc(r.domain)}</span><b>${esc(r.id)} · ${esc(r.failure)}</b><small>${r.parentId?'Upstream: '+esc(r.parentId):'Root risk'}<br>Review: ${esc(r.review)}</small></div>`).join('')}</div><div class="note">${state.apTable?'Configured AP reference: '+esc(state.apTable.source)+' / '+esc(state.apTable.revision)+'. '+state.apTable.rows.length+' tuples.':'Official Action Priority is not configured. Import your authorized reference table. Missing combinations remain unclassified.'}</div>${table(['Risk','S','O','D','Configured AP','Legacy RPN'],state.risks.map(r=>[esc(r.id),r.s,r.o,r.d,esc(E.apLookup(r.s,r.o,r.d,state.apTable).priority||'Unclassified'),r.s*r.o*r.d]))}${linkIssues.length?list(linkIssues):'<p class="muted">No missing references detected in the checked relationships.</p>'}</section>`+registry('risks',['domain','function','failure','effect','parentId','prevention','detection','review'])+registry('controlPlan',['riskId','characteristic','method','frequency','reaction','revision','approvedBy']);}
function apqpView(){const a=M.approvalGate(state);return title('APQP & submission readiness','Configure the customer route and retain evidence for every required deliverable.')+metrics([['Submission evidence',a.complete+'/'+a.total,a.status],['Required items',state.deliverables.filter(r=>r.required).length,'Customer-configured scope'],['Awaiting review',state.deliverables.filter(r=>r.status==='Review').length,'Named approval required'],['Unassigned',state.deliverables.filter(r=>!r.owner).length,'Ownership gaps']])+`<section class="card"><h2>Phase view</h2><div class="flow">${M.phases.map(p=>{const rows=state.deliverables.filter(r=>r.phase===p),done=rows.filter(r=>r.status==='Accepted'&&r.reference&&r.owner&&r.approvedBy).length;return `<div class="node"><b>${p}</b><span>${done}/${rows.length} reviewed</span><div class="bar"><span style="width:${rows.length?done/rows.length*100:0}%"></span></div></div>`;}).join('')}</div><p class="muted">This is an editable original workflow template. Required items cannot be satisfied by selecting “Not applicable”; change scope with a documented rationale and named reviewer.</p></section>`+registry('deliverables',['name','phase','required','status','owner','due','reference','approvedBy']);}
function auditView(){return title('Audit to action','Connect findings to evidence, actions and effectiveness. Record the exact applicable standard edition.')+registry('audits',['standard','requirement','finding','severity','owner','actionId','effectiveness','status'])+`<section class="card"><h2>Closure checks</h2>${state.audits.length?list(state.audits.map(a=>{const action=state.actions.find(x=>x.id===a.actionId),e=state.evidence.find(x=>x.id===a.evidenceId);const ok=a.status==='Verified'&&a.owner&&a.effectiveness&&e?.verifiedBy&&action?.status==='effective'&&action.validation&&action.verification;return a.id+': '+(ok?'Eligible for named auditor review':'Open evidence / action / effectiveness requirements');})):'<p class="muted">Add a finding to start. No official audit score is inferred.</p>'}</section>`;}
function valueView(){const r=E.roi(state.roi.investment,state.roi.baseline,state.roi.reduction,state.roi.attribution);return title('Value case & delivery services','Use explicit assumptions and a reviewable pilot scope. Forecast benefit is not achieved saving.')+`<div class="grid"><section class="card"><form id="roiForm"><h2>Single scenario</h2><div class="formgrid">${input('investment','Year-one total investment (€)',state.roi.investment,'number','min="1" step="any"')}${input('costBaseline','Annual eligible cost baseline (€)',state.roi.baseline,'number','min="0" step="any"')}${input('reduction','Expected preventable fraction (0–1)',state.roi.reduction,'number','min="0" max="1" step="0.01"')}${input('attribution','Attribution factor (0–1)',state.roi.attribution,'number','min="0" max="1" step="0.01"')}</div><p class="note">Use one non-overlapping cost baseline. Document supporting finance records before presenting a business case.</p><button class="primary">Calculate & save</button><p id="roiError" class="error"></p></form></section><section class="card"><h2>Forecast result</h2>${[['Annual benefit',fmt(r.forecastBenefit,0)+' €'],['Year-one net',fmt(r.net,0)+' €'],['Year-one ROI',pct(r.roi)],['Payback',r.paybackMonths===null?'No positive benefit':fmt(r.paybackMonths,1)+' months']].map(([k,v])=>`<div class="metricline"><span>${k}</span><b>${v}</b></div>`).join('')}</section></div><section class="card"><h2>Service delivery packages</h2><div class="grid three">${[['Measurement & SPC implementation','Define a characteristic, establish measurement suitability, select a rational study and validate reaction rules.','Outputs: approved study plan, reference datasets, calculation report and reaction plan.'],['Supplier escalation & 8D','Protect stock, establish causal evidence and verify corrective-action effectiveness.','Outputs: exposure register, three-leg investigation, tests, actions and customer report.'],['Connected Core Tools workshop','Link design, process and equipment risks to the Control Plan and submission evidence.','Outputs: linked risk register, change-impact list, review decisions and APQP deliverables.']].map(([a,b,c])=>`<article><h3>${a}</h3><p>${b}</p><small>${c}</small></article>`).join('')}</div><p class="note">Pilot acceptance: one agreed anonymized case completed end to end, independent calculation comparison, backup/restore exercise and named customer review. Scope and schedule are agreed during kickoff.</p><a href="documents/Delivery_Guide.html">Open the delivery and deployment guide</a></section>`;}
function learnView(){return title('Method library','Training notes, assumptions and examples remain available offline. Detailed engineering notes are in English.')+`<input class="search" id="methodSearch" placeholder="Search method, assumptions or example" aria-label="Search methods"><div class="methods" id="methodCards">${C.methods.map(([v,n,a,b,c,source])=>`<article class="card" data-method="${esc([n,a,b,c].join(' ').toLowerCase())}"><div class="cardtop"><h3>${n}</h3><button data-action="${v}">Open workbench</button></div><p>${a}</p><p class="note">${b}</p><p>${c}</p>${source?`<small>Reference: ${source}. See the source register for the external original.</small>`:''}</article>`).join('')}</div>`;}
function downloads(){return title('Downloads, integration & sources','The offline application has no runtime CDN, login, remote font or AI dependency.')+`<div class="grid"><section class="card"><h2>Local exports</h2><div class="stack">${btn('Full case JSON — backup / restore','export')}${btn('Measurement CSV','exportMeasurements')}${btn('Self-contained case report HTML','reportDownload')}${btn('Print case report to PDF','printReport')}${btn('AP reference import example','apExample')}</div><p class="note">For mobile offline use, download the single-file application and open it in a browser that executes local HTML. Some file-preview apps do not execute JavaScript. A hosted installation needs an initial online load.</p></section><section class="card"><h2>Release files</h2><div class="stack"><a class="linkcard" href="downloads/Quality_OS_Verification_Workbook.xlsx"><b>Verification workbook</b>Editable calculations, baseline data and cross-checks.</a><a class="linkcard" href="documents/Delivery_Guide.html"><b>Delivery & deployment guide</b>Offline use, GitHub, Netlify, integrations and acceptance.</a><a class="linkcard" href="documents/Source_Audit.html"><b>Source audit and capability register</b>Recovered modules, fixes and remaining scope.</a><a class="linkcard" href="downloads/Barkati_Quality_OS_Offline.html" download><b>Standalone offline application</b>Core interface, calculations, methods and case reports in one file.</a></div></section></div><section class="card"><h2>Current implementation boundary</h2><p>Local single-user engineering workbench. CSV/JSON file exchange is implemented. Direct SAP QM, AQDEF/Q-DAS, Minitab, PLM and CMMS connections are not activated or qualified. No remote LLM runs in this release. Multi-user authentication, permissions and tamper-proof audit records require the hosted backend phase.</p><p>Shell navigation supports EN/FR/DE. Engineering methods, data-field labels and generated reports use English in this release.</p></section><section class="card"><h2>Controlled source register</h2>${table(['ID','Source','Use / boundary'],C.sources.map(s=>[esc(s.id),`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.name)} ↗</a>`,esc(s.use)]))}<small>External source links need internet; all application calculations and authored method notes work offline. Reference check: 26 October 2026.</small></section>`;}
function render(){document.body.classList.toggle('dark',theme==='dark');document.documentElement.lang=lang;$('language').value=lang;$('theme').textContent=t('theme');['exportCase','importCase','report','demoCase','newCase'].forEach((id,i)=>$(id).textContent=t(['export','import','report','demo','newcase'][i]));$('nav').innerHTML=keys.map((k,i)=>`<a href="#${k}" class="${k===view?'active':''}"><span>${String(i+1).padStart(2,'0')}</span>${C.nav[lang][i]}</a>`).join('');$('crumb').textContent=C.nav[lang][keys.indexOf(view)]||'Case report';status();const fn={overview,case:caseView,spc:spcView,msa:msaView,tools:toolsView,eightd:eightdView,fmea:fmeaView,apqp:apqpView,audits:auditView,value:valueView,learn:learnView,downloads};$('main').innerHTML=fn[view]();wire();}
function go(v){if(!keys.includes(v))return;view=v;location.hash=v;document.body.classList.remove('menuopen');render();window.scrollTo(0,0);}
function download(name,content,type='text/plain'){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);}
function exportCase(){download(state.id.replace(/[^A-Za-z0-9_-]/g,'_')+'.json',JSON.stringify(state,null,2),'application/json');toast('Case backup exported. Keep the JSON file with your project evidence.');}
function csvCell(v){let s=String(v??'');if(/^[=+@]/.test(s)||/^-[^\d.]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
function exportRegistry(k){const fields=['id',...M.fields[k].map(f=>f[0])];download(state.id+'_'+k+'.csv',[fields,...state[k].map(r=>fields.map(f=>r[f]))].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv');}
function openEdit(k,id){edit={key:k,id};const r=id?state[k].find(x=>x.id===id):M.emptyRecord(k,k.slice(0,2).toUpperCase()+'-'+Date.now().toString(36));$('editTitle').textContent=(id?t('edit'):t('add'))+' · '+k;$('editFields').innerHTML=input('record-id','Stable record ID',r.id)+M.fields[k].map(([f,l,type])=>Array.isArray(type)?select('record-'+f,l,type,r[f]):type==='boolean'?select('record-'+f,l,[['true','Yes'],['false','No']],String(r[f])):type==='integer'||type==='rating'?input('record-'+f,l,r[f],'number',`step="1" min="${type==='rating'?1:0}" ${type==='rating'?'max="10"':''} required`):type==='date'?input('record-'+f,l,r[f],'date'):area('record-'+f,l,r[f])).join('');$('record-id').readOnly=!!id;$('formError').textContent='';$('deleteRecord').style.display=id?'':'none';$('saveRecord').textContent=t('save');$('editor').showModal();}
function form(id,handler){const el=$(id);if(el)el.onsubmit=e=>{e.preventDefault();try{handler();}catch(err){const target=$({spcForm:'calcError',msaForm:'msaError',toolsForm:'toolError',roiForm:'roiError',closureForm:'closureError'}[id]);if(target)target.textContent=err.message;else toast(err.message);}};}
function valueNumber(id){return E.cellNumber($(id).value,id);}
function wire(){form('caseForm',()=>{const draft=structuredClone(state);['owner','customer','product','process','equipment','characteristic'].forEach(k=>draft[k]=$(k).value.trim());draft.title=$('caseTitle').value.trim();draft.synthetic=$('synthetic').value==='true';draft.spec={name:$('specName').value,unit:$('unit').value,drawing:$('drawing').value,lsl:valueNumber('lsl'),usl:valueNumber('usl'),required:valueNumber('required')};M.validate(draft);state=draft;save('Case context/specification updated');render();toast('Case saved.');});
 form('spcForm',()=>{const groups=E.matrix($('measurements').value),options={mode:$('chartMode').value,baseline:valueNumber('baseline'),extended:$('extended').checked};E.spc(groups,{...options,...state.spec});state.study={...options,groups};state.governance.reviewer='';save('Measurement study updated; reviewer cleared');render();toast('Study calculated and saved.');});
 form('governanceForm',()=>{state.governance={msaEvidence:$('msaEvidence').value.trim(),modelEvidence:$('modelEvidence').value.trim(),reviewer:$('reviewer').value.trim()};save('Statistical review evidence updated');render();});
 form('problemForm',()=>{['team','what','where','when','howMany','isNot','lessons'].forEach(k=>state.investigation[k]=$('problem-'+k).value.trim());save('Problem definition updated');render();});
 form('closureForm',()=>{E.need(E.eightDGates(state).slice(0,7).every(g=>g.eligible),'D1–D7 must be ready before closure.');const approver=$('closureApprover').value.trim(),ref=$('closureReference').value.trim(),date=$('closureDate').value;E.need(approver&&ref&&date,'Approver, reference and date are required.');M.record(state,'Human closure recorded');state.investigation.approver=approver;state.investigation.approvalReference=ref;state.investigation.closureDate=date;save();render();});
 form('roiForm',()=>{const r={investment:valueNumber('investment'),baseline:valueNumber('costBaseline'),reduction:valueNumber('reduction'),attribution:valueNumber('attribution')};E.roi(r.investment,r.baseline,r.reduction,r.attribution);state.roi=r;save('Forecast assumptions updated');render();});
 form('msaForm',calculateMSA);form('toolsForm',calculateTool);
 if($('msaType'))$('msaType').onchange=()=>{msaType=$('msaType').value;msaLast=null;render();};if($('toolType'))$('toolType').onchange=()=>{tool=$('toolType').value;toolLast=null;render();};if($('methodSearch'))$('methodSearch').oninput=e=>document.querySelectorAll('[data-method]').forEach(el=>el.hidden=!el.dataset.method.includes(e.target.value.toLowerCase()));}
function calculateMSA(){const text=$('msaData').value,tol=valueNumber('tolerance'),ref=valueNumber('reference');let result;const rows=msaType==='resolution'?null:E.parseCSV(text);
 if(msaType==='crossed'||msaType==='nested'){E.need(rows.every(r=>r.length===3),'Expected part,operator,value columns.');result=E.grr(rows.map((r,i)=>({part:r[0],operator:r[1],value:E.cellNumber(r[2],'Reading '+(i+1))})),msaType==='nested',tol);}
 else if(msaType==='attribute'){E.need(rows.every(r=>r.length===2),'Expected two rating columns.');result=E.kappa(rows.map(r=>r[0]),rows.map(r=>r[1]));}
 else if(msaType==='linearity')result=E.linearity(E.matrix(text));
 else if(msaType==='resolution'){const res=valueNumber('resolution');E.need(res>0&&tol>0,'Resolution and tolerance must be positive.');result={tolerance:tol,resolution:res,toleranceIncrements:tol/res};}
 else{const m=E.matrix(text);E.need(m.every(r=>r.length===1),'Expected one value per row.');const vals=m.flat();result=msaType==='type1'?E.type1(vals,ref,tol,valueNumber('fraction')):msaType==='stability'?E.spc(m,{mode:'imr',baseline:m.length}):E.bias(vals,ref);}
 msaLast={type:msaType,inputs:{text,reference:ref,tolerance:tol,fraction:valueNumber('fraction'),resolution:valueNumber('resolution')},result};state.msaDraft={type:msaType,text};save();$('msaError').textContent='';$('msaResult').innerHTML=(result.main?chart(result.main,result.baseline)+chart(result.disp,result.baseline-1):resultMetrics(result))+(result.components?'<h3>Variance components</h3>'+resultMetrics(result.components):'')+(result.model?`<p class="note">${esc(result.model)}. ${esc(result.notes)}</p>`:'')+(msaType==='stability'?'<p>Study is preliminary if fewer than 25 baseline readings. Interpret both charts.</p>':'')+`<p class="note">Result is a study estimate. Acceptability depends on the measurement task and customer criteria.</p>${btn('Add study to evidence','msaEvidence')}`;}
function calculateTool(){let r;const text=$('toolData').value;if(tool==='sampling'){const n=valueNumber('sampleN'),c=valueNumber('sampleC'),p=valueNumber('defectP'),pa=E.binomialAcceptance(n,c,p);r={n,c,p,probabilityAccept:pa,probabilityReject:1-pa};const ps=Array.from({length:21},(_,i)=>i*.01),ys=ps.map(v=>E.binomialAcceptance(n,c,v));$('toolResult').innerHTML=resultMetrics(r)+table(['Defect probability','P(accept)'],ps.map((v,i)=>[pct(v),pct(ys[i])]))+'<p class="note">Binomial model. No official AQL table or finite-population correction.</p>';}
 else if(tool==='pareto'){const rows=E.parseCSV(text);E.need(rows.every(r=>r.length===2),'Expected category,count.');r=E.pareto(rows.map((x,i)=>[x[0],E.cellNumber(x[1],'Count '+(i+1))]));$('toolResult').innerHTML=table(['Category','Count','Cumulative'],r.map(x=>[esc(x.category),x.count,pct(x.cumulative)]));}
 else if(tool==='histogram'){const m=E.matrix(text);E.need(m.every(r=>r.length===1),'Histogram expects one value per row.');r=E.histogram(m.flat());const max=Math.max(...r.map(x=>x.count));$('toolResult').innerHTML=r.map(x=>`<small>${fmt(x.lower)}–${fmt(x.upper)} · ${x.count}</small><div class="bar"><span style="width:${x.count/max*100}%"></span></div>`).join('');}
 else if(tool==='scatter'){const m=E.matrix(text);E.need(m.every(r=>r.length===2),'Scatter expects x,y pairs.');r=E.regression(m.map(x=>x[0]),m.map(x=>x[1]));$('toolResult').innerHTML=scatterPlot(m)+resultMetrics(r)+'<p class="note">Association does not demonstrate causation. Check residuals and process knowledge.</p>';}
 else{r=E.attributeChart(E.matrix(text),tool);$('toolResult').innerHTML=chart(r)+list(r.signals.map(x=>x.rule+' at row '+x.at));}
 toolLast={type:tool,text,result:r};$('toolError').textContent='';$('toolResult').insertAdjacentHTML('beforeend',btn('Add analysis to evidence','toolEvidence'));}
function scatterPlot(rows){const xs=rows.map(r=>r[0]),ys=rows.map(r=>r[1]),loX=Math.min(...xs),hiX=Math.max(...xs),loY=Math.min(...ys),hiY=Math.max(...ys);return `<svg class="chart" viewBox="0 0 600 300" aria-label="Scatter plot" role="img"><line class="axis" x1="40" y1="260" x2="570" y2="260"/><line class="axis" x1="40" y1="20" x2="40" y2="260"/>${rows.map(([x,y])=>`<circle class="point" cx="${40+(x-loX)/(hiX-loX||1)*530}" cy="${260-(y-loY)/(hiY-loY||1)*240}" r="4"><title>${x}, ${y}</title></circle>`).join('')}<text x="40" y="285" font-size="12">x ${fmt(loX)} to ${fmt(hiX)} · y ${fmt(loY)} to ${fmt(hiY)}</text></svg>`;}
function addAnalysis(data,kind){if(!data)return;const id='EV-'+Date.now().toString(36);state.evidence.push({id,title:data.type+' study',source:'Local calculation / engine '+E.VERSION,statement:JSON.stringify(data.result),verifiedBy:''});const field=kind==='msa'?'msaStudies':'analyses';state[field]=state[field]||[];state[field].push({...data,at:new Date().toISOString(),evidenceId:id});save('Added '+data.type+' calculation to evidence');toast('Evidence saved as '+id+'. Add a named verification after review.');}
function reportHTML(){const s=study(),g=E.gate(state,s),gates=E.eightDGates(state);let html=`<div class="reportsection"><span class="eyebrow">Barkati Quality OS · case report</span><h1>${esc(state.title)}</h1><p>${esc(state.id)} · revision ${state.revision} · ${esc(new Date().toISOString())}</p><p>${state.synthetic?'SYNTHETIC DEMONSTRATION — NOT CUSTOMER EVIDENCE':'USER CASE — approval status shown below'}</p>${table(['Product','Process','Characteristic','Owner'],[[esc(state.product),esc(state.process),esc(state.characteristic),esc(state.owner)]])}<h2>Statistical decision</h2><strong>${g.status}</strong>${list(g.blocks)}</div>`;
 if(s)html+=`<section class="reportsection"><h2>Measurement study</h2><p>${s.mode} · ${s.baseline} baseline rows / ${s.rows} total · ${s.n} per subgroup. Capability period: baseline only.</p>${table(['Cp','Cpk','Pp','Ppk','Within sigma','Overall sigma'],[[fmt(s.capability.cp),fmt(s.capability.cpk),fmt(s.capability.pp),fmt(s.capability.ppk),fmt(s.within,6),fmt(s.overall,6)]])}${chart(s.main,s.baseline)}${chart(s.disp,s.baseline-(s.disp.offset||0))}</section>`;
 html+=`<section class="reportsection pagebreak"><h2>8D discipline gates</h2>${table(['Gate','Prerequisites','Status'],gates.map(x=>[x.id,esc(x.reason),x.eligible?'READY':'BLOCKED']))}<h2>Problem definition</h2>${table(['Field','Record'],Object.entries(state.investigation).map(([k,v])=>[esc(k),esc(v)]))}</section>`;
 for(const key of Object.keys(M.fields)){const ff=M.fields[key];html+=`<section class="reportsection"><h2>${esc(key)}</h2>${state[key].length?state[key].map(r=>'<h3>'+esc(r.id)+'</h3>'+table(['Field','Record'],ff.map(([k,l])=>[esc(l),esc(r[k])]))).join(''):'<p>No record.</p>'}</section>`;}
 html+='<section class="reportsection"><h2>Calculation and record boundaries</h2><p>Engineering review record, not automatic product approval. Normal-model capability assumptions must be reviewed. Local activity history is not tamper-proof. Sources and formulas are included in the accompanying delivery guide.</p><p>Mohamed Barkati · +216 50129234</p></section>';return html;}
function reportDownload(){const html='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(state.id)+' case report</title><style>body{font:14px Arial,sans-serif;color:#163043;max-width:1200px;padding:35px;margin:auto}h1{font-size:30px}h2{margin-top:30px}table{border-collapse:collapse;width:100%;font-size:11px}td,th{padding:8px;border:1px solid #cad6dd;text-align:left;overflow-wrap:anywhere}.scroll{overflow:auto}.chart{width:100%;max-height:320px}.chart text{fill:#50697b}.axis{stroke:#dce5eb}.limit{stroke:#a33043;stroke-dasharray:5 4}.center{stroke:#007d77;stroke-dasharray:3 3}.series{stroke:#007d77;stroke-width:2;fill:none}.point{fill:#007d77}.signal{fill:#a33043}.eyebrow{color:#007d77}tr{break-inside:avoid}@media print{.pagebreak{break-before:page}.scroll{overflow:visible}body{padding:0}}</style>'+reportHTML()+'</html>';download(state.id+'_report.html',html,'text/html');}
function printReport(){const previous=view;$('main').innerHTML=reportHTML();requestAnimationFrame(()=>{window.print();view=previous;render();});}
const actions={overview:()=>go('overview'),case:()=>go('case'),spc:()=>go('spc'),msa:()=>go('msa'),tools:()=>go('tools'),eightd:()=>go('eightd'),fmea:()=>go('fmea'),apqp:()=>go('apqp'),audits:()=>go('audits'),value:()=>go('value'),learn:()=>go('learn'),export:exportCase,importMeasurements:()=>$('dataFile').click(),exportMeasurements:()=>download(state.id+'_measurements.csv',state.study.groups.map(r=>r.join(',')).join('\r\n'),'text/csv'),msaDemo:()=>{$('msaData').value=msaDemo(msaType);},msaEvidence:()=>addAnalysis(msaLast,'msa'),toolEvidence:()=>addAnalysis(toolLast,'tool'),apImport:()=>$('apFile').click(),apExample:()=>download('AP_reference_format.json',JSON.stringify({source:'Replace with authorized source',revision:'Replace with edition',rows:[]},null,2),'application/json'),reportDownload,printReport,tour:()=>{toast('Demonstration: inspect both SPC charts → create investigation → add evidence/tests → link FMEA and Control Plan → export case.');go('spc');},investigate:()=>{const s=study();E.need(s,'Calculate a valid study first.');state.investigation.what=`${s.signals.length} selected chart signal(s) for ${state.spec.name}; no causal conclusion.`;state.investigation.where=state.process;state.investigation.when='Define production time / lots corresponding to signalled rows';state.investigation.howMany=String(s.capability.outOfSpec)+' observed out-of-spec readings; suspect population to establish';const id='EV-SPC-'+Date.now().toString(36);state.evidence.push({id,title:'SPC signal snapshot',source:'Engine '+E.VERSION+' / case revision '+state.revision,statement:JSON.stringify({signals:s.signals,baseline:s.baseline,capability:s.capability}),verifiedBy:''});save('Investigation opened from SPC signal snapshot');go('eightd');},propagate:()=>{state.risks.forEach(r=>r.review='Under review');state.controlPlan.forEach(r=>r.approvedBy='');save('All linked case risk/control records flagged for review; ratings unchanged');render();toast('Risk reviews reopened. Existing ratings were preserved.');}};
document.addEventListener('click',e=>{const localLink=e.target.closest('a[href]');if(localLink&&window.OFFLINE_FILES){const path=localLink.getAttribute('href'),f=window.OFFLINE_FILES[path];if(f){e.preventDefault();const bytes=Uint8Array.from(atob(f.base64),c=>c.charCodeAt(0));download(f.name,bytes,f.mime);return;}if(path==='downloads/Barkati_Quality_OS_Offline.html'){e.preventDefault();download('Barkati_Quality_OS_Offline.html','<!doctype html>'+document.documentElement.outerHTML,'text/html');return;}}const action=e.target.closest('[data-action]');if(action){try{actions[action.dataset.action]?.();}catch(err){toast(err.message);}}const add=e.target.closest('[data-add]');if(add)openEdit(add.dataset.add);const ed=e.target.closest('[data-edit]');if(ed)openEdit(ed.dataset.edit,ed.dataset.id);const csv=e.target.closest('[data-csv]');if(csv)exportRegistry(csv.dataset.csv);});
$('editForm').onsubmit=e=>{e.preventDefault();try{const k=edit.key,r={id:$('record-id').value.trim()};for(const [f,,type] of M.fields[k])r[f]=type==='integer'||type==='rating'?valueNumber('record-'+f):type==='boolean'?$('record-'+f).value==='true':$('record-'+f).value.trim();M.validRecord(k,r);E.need(!state[k].some(x=>x.id===r.id&&x.id!==edit.id),'Duplicate ID.');if(edit.id)state[k][state[k].findIndex(x=>x.id===edit.id)]=r;else state[k].push(r);save(k+' record '+r.id+' saved');$('editor').close();render();}catch(err){$('formError').textContent=err.message;}};
$('cancelEditor').onclick=()=>$('editor').close();$('deleteRecord').onclick=()=>{if(confirm('Delete '+edit.id+'? Linked records may require repair.')){state[edit.key]=state[edit.key].filter(r=>r.id!==edit.id);save('Deleted '+edit.key+' '+edit.id);$('editor').close();render();}};
$('menu').onclick=()=>document.body.classList.toggle('menuopen');$('theme').onclick=()=>{theme=theme==='dark'?'light':'dark';try{localStorage.setItem(storage+'-theme',theme);}catch{}render();};$('language').onchange=e=>{lang=e.target.value;try{localStorage.setItem(storage+'-lang',lang);}catch{}render();};$('exportCase').onclick=exportCase;$('importCase').onclick=()=>$('caseFile').click();$('report').onclick=()=>{$('main').innerHTML='<div class="row noprint">'+btn('Print / save PDF','printReport','primary')+btn('Download report HTML','reportDownload')+btn('Return to case','overview')+'</div>'+reportHTML();window.scrollTo(0,0);};
$('caseFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;E.need(f.size<=8e6,'Case JSON must be ≤8 MB.');const raw=JSON.parse(await f.text()),draft=raw.schemaVersion==='dqos.case.1.0'?M.migrateV3(raw):M.validate(raw);if(!confirm('Replace the current local case? Export it first if needed.'))return;state=draft;save();render();toast('Imported case. Recalculated results come from the included raw readings.');}catch(err){toast(err.message);}finally{e.target.value='';}};
$('dataFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;E.need(f.size<=4e6,'CSV must be ≤4 MB.');const text=await f.text();E.matrix(text);if(view!=='spc')go('spc');$('measurements').value=text;toast('CSV loaded. Review baseline and calculate to save.');}catch(err){toast(err.message);}finally{e.target.value='';}};
$('apFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;E.need(f.size<=500000,'AP reference file is too large.');state.apTable=E.validateAP(JSON.parse(await f.text()));save('Imported AP source '+state.apTable.source+' / '+state.apTable.revision);render();}catch(err){toast(err.message);}finally{e.target.value='';}};
$('demoCase').onclick=()=>{if(confirm('Replace the current case with synthetic data? Export your case first.')){state=M.demo();save();go('overview');}};$('newCase').onclick=()=>{if(confirm('Create a blank case? Export your existing case first.')){state=M.demo();state.id='CASE-'+Date.now().toString(36).toUpperCase();state.title='New engineering case';state.synthetic=false;state.customer='';state.product='';state.process='';state.equipment='';state.study.groups=[];state.risks=[];state.controlPlan=[];state.spec.drawing='';save();go('case');}};
window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(keys.includes(h)&&h!==view){view=h;render();}});view=keys.includes(location.hash.slice(1))?location.hash.slice(1):'overview';render();
})();
